  function uniformItemSelectionHtml(i,existing){const cfg=uniformConfig(i);applyUniformConfig(i,cfg);const st=uniformStockStats(cfg);return '<section class="portal-edit-section kids-uniform-editor"><header><div><b>Variants, sizes & stock</b><small>Add and name every variant yourself. Nothing is added by default.</small></div></header><fieldset><div class="uniform-inline-create"><label for="uniformNewOptionTitle">Add a variant</label><div><input id="uniformNewOptionTitle" type="text" maxlength="80" data-uniform-new-option-title placeholder="Type a variant name, colour, style, etc."><button type="button" data-uniform-add-option>+ Add variant</button></div></div><div class="kids-uniform-stock-analysis four"><span><small>Total stock</small><b>'+st.total+'</b></span><span><small>Variants</small><b>'+st.items+'</b></span><span><small>Low sizes</small><b>'+st.low+'</b></span><span><small>Out sizes</small><b>'+st.out+'</b></span></div><div class="kids-uniform-part-block"><div class="kids-uniform-section-title"><b>Variant details</b><small>Rename, reorder, add images, stock, prices and descriptions here</small></div>'+(uniformAllVariants(cfg).length?'<div class="kids-uniform-admin-grid">'+uniformAllVariants(cfg).map(v=>uniformVariantAdminCard(v,'Custom')).join('')+'</div>':'<p class="uniform-inline-empty">No variants yet. Type a variant title above and press Add variant to begin.</p>')+'</div>'+uniformDescriptionAdmin(cfg)+(existing?'<button type="button" class="primary-btn kids-uniform-save" data-save-uniform-setup>Save variant setup</button>':'')+'</fieldset></section>';}

