      const typeCards=(state.customSportswearTypes||[]).map(t=>{const key='itemsportstype:'+t.id,editing=!existing||!!state.editFields[key],enabled=typeIds.has(String(t.id)),adj=Number(t.price_adjustment||0),adjText=t.is_base?'Base Round Neck rate':(adj>=0?'+':'−')+money(Math.abs(adj))+' from Round Neck';return '<article class="item-fabric-card sportswear-item-type-card '+(enabled?'selected':'')+' '+(t.active===false?'inactive':'')+'" data-item-sports-type-row="'+t.id+'"><div class="item-fabric-top"><label class="fabric-check"><input type="checkbox" data-item-sports-type-enable="'+t.id+'" '+(enabled?'checked':'')+' '+(editing?'':'disabled')+'><span><b>'+esc(t.name)+'</b><small>'+esc(adjText)+(t.active===false?' · Hidden globally':'')+'</small></span></label>'+(existing?'<button type="button" class="field-edit-button '+(editing?'done':'')+'" data-edit-item-sports-type="'+t.id+'">'+(editing?I('check')+'<span>Done</span>':I('edit')+'<span>Edit</span>')+'</button>':'')+'</div></article>';}).join('');
