    const media='<div class="upload-zone custom-upload-zone"><input id="customItemImages" type="file" accept="image/*" '+(uniform?'':'multiple')+'><div><b>'+(uniform?'Card image':'Upload item images')+'</b><small>'+(uniform?'Shown on the catalogue card. Option images are managed below.':'Main catalogue images.')+'</small></div></div><div class="image-preview-grid custom-image-preview-grid">'+(i.images||[]).slice(0,uniform?1:99).map((src,n)=>'<div class="image-chip">'+img(src,i.title)+'<button type="button" data-remove-custom-image="'+n+'">×</button></div>').join('')+'</div>';
    const detailsSection='<section class="portal-edit-section custom-field-section"><header><div><b>Item details</b><small>'+(existing?'Edit a field, then tap Done.':'Name, category and short description.')+'</small></div></header><fieldset>'+details+'</fieldset></section>';
    const mediaSection='<section class="portal-edit-section custom-media-section"><header><div><b>'+(uniform?'Card image':'Item images')+'</b><small>'+(uniform?'One card image for the catalogue listing.':'Main customer-facing images.')+'</small></div></header><fieldset>'+media+'</fieldset></section>';
